function draw(){const dpr=Math.min(devicePixelRatio||1,2);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,screenW,screenH);ctx.save();ctx.translate(offsetX,offsetY);ctx.scale(scale,scale);drawWater();ctx.save();if(shake>0){ctx.translate(rand(-shake,shake),rand(-shake,shake));shake*=.88}drawIsland();drawPickups();drawOil();drawPlayers();drawParticles();ctx.restore();ctx.restore();}
function drawWater(){const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#1b3850');g.addColorStop(.55,'#163347');g.addColorStop(1,'#11283c');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.strokeStyle='#6dd8d21a';ctx.lineWidth=1;for(let i=0;i<11;i++){const y=65+i*58+Math.sin(elapsed*.5+i)*8;ctx.beginPath();for(let x=0;x<=W;x+=16){const yy=y+Math.sin(x*.018+i*1.7+elapsed*.65)*4;if(x===0)ctx.moveTo(x,yy);else ctx.lineTo(x,yy)}ctx.stroke()}for(let i=0;i<22;i++){const x=(i*173+elapsed*12)%W,y=(i*97+Math.sin(elapsed*.5+i)*40+H)%H;ctx.fillStyle=i%2?'#a0f4e00c':'#d7ffec12';ctx.fillRect(x,y,rand(10,25),2)}}
function drawIsland(){// floating, chunky pixel-art island and layered cliff
ctx.save();ctx.translate(0,5);ctx.fillStyle='#06152188';ctx.beginPath();ctx.ellipse(CX,CY+15,arena.rx+18,arena.ry+19,0,0,TAU);ctx.fill();ctx.restore();
ctx.fillStyle='#b97651';ctx.beginPath();ctx.ellipse(CX,CY+8,arena.rx+8,arena.ry+8,0,0,TAU);ctx.fill();ctx.fillStyle='#df9a61';ctx.beginPath();ctx.ellipse(CX,CY+1,arena.rx,arena.ry,0,0,TAU);ctx.fill();ctx.fillStyle='#4dbd84';ctx.beginPath();ctx.ellipse(CX,CY-7,arena.rx-6,arena.ry-6,0,0,TAU);ctx.fill();
// chunky irregular turf patches
for(let i=0;i<23;i++){const a=i*TAU/23+.1,rr=.84+(i%3)*.035,x=CX+Math.cos(a)*arena.rx*rr,y=CY-7+Math.sin(a)*arena.ry*rr;ctx.fillStyle=i%2?'#3da975':'#61cb85';ctx.fillRect(Math.round(x/8)*8,Math.round(y/8)*8,18,11)}
// central path
ctx.fillStyle='#d9bb78';ctx.beginPath();ctx.moveTo(420,345);ctx.lineTo(458,314);ctx.lineTo(532,329);ctx.lineTo(574,365);ctx.lineTo(551,396);ctx.lineTo(477,383);ctx.lineTo(435,402);ctx.closePath();ctx.fill();ctx.fillStyle='#efd38e';ctx.fillRect(466,332,56,10);ctx.fillRect(499,360,47,10);
// tiny checker-like decorations and reed islands
for(const [x,y,c] of [[333,279,'#ffb35a'],[646,305,'#f77b70'],[416,446,'#81a8ff'],[583,252,'#ffcf68'],[362,397,'#efa0dc'],[610,426,'#9bda70']]){ctx.fillStyle='#286d62';ctx.fillRect(x-9,y+8,20,7);ctx.fillStyle=c;ctx.fillRect(x-7,y,16,13);ctx.fillStyle='#fff4c2';ctx.fillRect(x-4,y+3,4,4)}
// little palms and rocks
for(const [x,y] of [[312,350],[695,365],[389,245],[605,457],[500,260],[456,449]]){ctx.fillStyle='#2c775c';ctx.fillRect(x-8,y+7,17,7);ctx.fillStyle='#72574a';ctx.fillRect(x-4,y,8,11);ctx.fillStyle='#82d58b';ctx.fillRect(x-11,y-6,11,7);ctx.fillRect(x+3,y-9,11,7);ctx.fillRect(x-3,y-12,9,7)}
// cracks and warning markers as the shrinking island erodes
for(const c of cracks){ctx.globalAlpha=clamp(c.life/2,0,1);ctx.strokeStyle='#653a37';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.lineTo(c.x+7,c.y+10);ctx.lineTo(c.x-3,c.y+17);ctx.lineTo(c.x+6,c.y+23);ctx.stroke();ctx.globalAlpha=1}
const danger=clamp((elapsed-38)/110,0,1);if(danger>.05){ctx.strokeStyle=`rgba(255,111,104,${.16+Math.sin(elapsed*3)*.08})`;ctx.lineWidth=2;ctx.setLineDash([6,8]);ctx.beginPath();ctx.ellipse(CX,CY,arena.rx-2,arena.ry-2,0,0,TAU);ctx.stroke();ctx.setLineDash([])}
// top-down shadow lip scallops
ctx.strokeStyle='#286a63';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(CX,CY-6,arena.rx-8,arena.ry-8,0,0,TAU);ctx.stroke();}
function drawPickups(){for(const b of pickups){const pulse=Math.sin(elapsed*5+b.phase)*2;const colors={mega:'#ffb950',oil:'#8da4ff',spike:'#a9eaff',hook:'#d3a4ff'},glyph={mega:'✚',oil:'◉',spike:'✦',hook:'↗'};ctx.save();ctx.translate(b.x,b.y+pulse);ctx.fillStyle='#10203988';ctx.fillRect(-13,10,26,6);ctx.fillStyle='#28334a';ctx.fillRect(-13,-12,26,24);ctx.fillStyle=colors[b.type];ctx.fillRect(-10,-14,20,21);ctx.fillStyle='#fff9d8';ctx.fillRect(-5,-10,5,4);ctx.fillStyle='#1c293c';ctx.font='bold 14px Nunito';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(glyph[b.type],0,0);ctx.strokeStyle=colors[b.type]+'99';ctx.lineWidth=2;ctx.strokeRect(-15,-18,30,31);ctx.restore()}}
function drawOil(){for(const o of oils){ctx.globalAlpha=clamp(o.life/4,0,1)*.52;ctx.fillStyle='#6572b9';ctx.beginPath();ctx.ellipse(o.x,o.y,12,8,0,0,TAU);ctx.fill();ctx.fillStyle='#b4c6ff';ctx.fillRect(o.x-4,o.y-2,4,2)}ctx.globalAlpha=1}
function drawPlayers(){for(const p of players){if(!p.alive)continue;const mega=p.power==='mega',r=p.r*(mega?1.75:1),blink=p.invuln>0&&Math.floor(elapsed*14)%2===0;if(blink)ctx.globalAlpha=.5;
ctx.fillStyle='#163a45';ctx.beginPath();ctx.ellipse(p.x,p.y+r*.74,r*1.1,r*.48,0,0,TAU);ctx.fill();
// legs kick wildly while moving
const moving=Math.hypot(p.vx,p.vy)>22,wiggle=moving?Math.sin(elapsed*19+p.id)*4:0;ctx.fillStyle='#28354a';ctx.fillRect(p.x-r*.55+wiggle,p.y+r*.35,r*.47,r*.48);ctx.fillRect(p.x+r*.15-wiggle,p.y+r*.35,r*.47,r*.48);ctx.fillStyle='#f4d18c';ctx.fillRect(p.x-r*.62+wiggle,p.y+r*.69,r*.52,r*.2);ctx.fillRect(p.x+r*.13-wiggle,p.y+r*.69,r*.52,r*.2);
// colorful round body with thick pixel outline
ctx.fillStyle='#26344a';ctx.beginPath();ctx.arc(p.x,p.y,r,0,TAU);ctx.fill();ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y-1,r*.84,0,TAU);ctx.fill();ctx.fillStyle='#ffffff38';ctx.fillRect(p.x-r*.38,p.y-r*.52,r*.5,4);
// face follows movement direction
const fx=Math.cos(p.face)*r*.23,fy=Math.sin(p.face)*r*.2;ctx.fillStyle='#152238';ctx.fillRect(p.x-r*.29+fx,p.y-r*.12+fy,4,5);ctx.fillRect(p.x+r*.08+fx,p.y-r*.12+fy,4,5);ctx.fillStyle='#fff';ctx.fillRect(p.x-r*.25+fx,p.y-r*.12+fy,2,2);ctx.fillRect(p.x+r*.12+fx,p.y-r*.12+fy,2,2);ctx.fillStyle='#8c3d46';ctx.fillRect(p.x-r*.08+fx,p.y+r*.18+fy,6,2);
if(p.power==='spike'){ctx.strokeStyle='#ccf5ff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(p.x,p.y,r+6+Math.sin(elapsed*8)*2,0,TAU);ctx.stroke();for(let i=0;i<8;i++){const a=i*TAU/8;ctx.fillStyle='#e3fbff';ctx.beginPath();ctx.moveTo(p.x+Math.cos(a)*(r+2),p.y+Math.sin(a)*(r+2));ctx.lineTo(p.x+Math.cos(a)*(r+12),p.y+Math.sin(a)*(r+12));ctx.lineTo(p.x+Math.cos(a+.25)*(r+2),p.y+Math.sin(a+.25)*(r+2));ctx.fill()}}
if(p.power==='mega'){ctx.fillStyle='#f8c858';ctx.fillRect(p.x-r*.52,p.y-r*.82,r*1.04,5);ctx.fillStyle='#fff1ae';ctx.fillRect(p.x-r*.36,p.y-r*.95,6,5)}
if(p.power==='oil'){ctx.fillStyle='#a5b1ff';ctx.fillRect(p.x-r*.75,p.y-r*.92,7,5)}
if(p===me){ctx.fillStyle='#ecffab';ctx.beginPath();ctx.moveTo(p.x,p.y-r-15);ctx.lineTo(p.x-6,p.y-r-24);ctx.lineTo(p.x+6,p.y-r-24);ctx.fill();ctx.strokeStyle='#eaffb0';ctx.lineWidth=1;ctx.beginPath();ctx.arc(p.x,p.y,r+4,0,TAU);ctx.stroke()}
ctx.font=`800 ${p===me?12:10}px Nunito`;ctx.textAlign='center';ctx.textBaseline='bottom';ctx.fillStyle='#14213a';ctx.fillRect(p.x-(p.name.length*3.2)-3,p.y-r-14,p.name.length*6.4+6,13);ctx.fillStyle=p===me?'#eaffab':'#fff';ctx.fillText(p.name,p.x,p.y-r-3);ctx.globalAlpha=1}}
function drawParticles(){for(const q of particles){ctx.globalAlpha=clamp(q.life/q.max,0,1);ctx.fillStyle=q.color;ctx.fillRect(Math.round(q.x),Math.round(q.y),q.size,q.size)}ctx.globalAlpha=1}
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);draw();requestAnimationFrame(frame)}

