files.patch:
Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -19,4 +19,32 @@
 <div class="mobile-controls"><div class="stick" id="stick"></div><button class="dash-button" id="dashBtn">¡DASH!</button></div>
 <div class="overlay" id="startOverlay"><div class="modal"><div class="modal-kicker">✦ Isla en problemas · ronda 01 ✦</div><h1>¡SÁLVESE<br><span>QUIEN PUEDA!</span></h1><p>Una isla. Un montón de gente. Cero modales. Empuja a los demás antes de que el suelo desaparezca.</p><div class="feature-row"><span class="feature">⏱ 3 MIN DE CAOS</span><span class="feature">✹ 7 RIVALES BOT</span><span class="feature">⚡ PODERES LOCOS</span></div><button class="cta" id="startBtn">¡ENTRAR A LA ISLA! →</button><div class="footnote">WASD / FLECHAS PARA MOVER · ESPACIO PARA EMBESTIR</div></div></div>
 <div class="overlay hidden" id="endOverlay"><div class="modal podium"><div class="modal-kicker">✦ FIN DE LA RONDA ✦</div><h1>REYES DE<br><span>LA ISLA</span></h1><p>El caos ha hablado. Estos son los que más empujaron.</p><div class="podium-list" id="podiumList"></div><button class="cta" id="againBtn">¡OTRA RONDA! ↻</button></div></div>
 <script>
+'use strict';
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
+const W=1000,H=700,CX=500,CY=350,TAU=Math.PI*2,palette=['#ff7168','#65d9ce','#ffc857','#a996ff','#80d872','#ff9fca','#5eaeff','#f2f1e8'],names=['Tostadita','Don Croqueta','Pato Loco','Chispa','Capitán Caos','Limón','Trompo','TÚ'];
+let players=[],pickups=[],particles=[],cracks=[],oils=[],running=false,remaining=180,last=performance.now(),elapsed=0,scale=1,offsetX=0,offsetY=0,shake=0,screenW=0,screenH=0,toastTimer=0,me,input={x:0,y:0,dash:false},keys={},touchVector={x:0,y:0};
+const arena={rx:360,ry:250};
+function resize(){const dpr=Math.min(devicePixelRatio||1,2);screenW=innerWidth;screenH=innerHeight;canvas.width=Math.floor(screenW*dpr);canvas.height=Math.floor(screenH*dpr);canvas.style.width=screenW+'px';canvas.style.height=screenH+'px';scale=Math.min(screenW/(W+50),screenH/(H+60));offsetX=(screenW-W*scale)/2;offsetY=(screenH-H*scale)/2;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
+const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
+function createPlayers(){players=[];names.forEach((name,i)=>players.push({id:i,name,color:palette[i],x:CX+rand(-130,130),y:CY+rand(-100,100),vx:0,vy:0,r:i===7?14:13,score:0,kos:0,alive:true,respawn:0,bot:i!==7,dir:rand(0,TAU),think:rand(.4,2),dash:0,invuln:0,power:null,powerTime:0,oil:0,stunned:0,face:0,spin:0,hitTime:-99,lastHit:null}));me=players[7];players.forEach(p=>{if(p!==me){p.x=CX+rand(-240,240);p.y=CY+rand(-160,160)}})}
+function spawnPickup(){const types=['mega','oil','spike','hook'],type=types[Math.floor(Math.random()*types.length)],a=rand(0,TAU),rr=Math.sqrt(Math.random())*.67;pickups.push({x:CX+Math.cos(a)*arena.rx*rr,y:CY+Math.sin(a)*arena.ry*rr,type,phase:rand(0,TAU),life:20})}
+function startGame(){createPlayers();pickups=[];particles=[];cracks=[];oils=[];remaining=180;elapsed=0;arena.rx=360;arena.ry=250;running=true;last=performance.now();document.getElementById('startOverlay').classList.add('hidden');document.getElementById('endOverlay').classList.add('hidden');for(let i=0;i<4;i++)spawnPickup();showToast('¡A EMPUJAR! 💥')}
