function drawPickups(){for(const b of pickups){const bob=Math.sin(elapsed*4+b.phase)*4;ctx.save();ctx.translate(b.x,b.y+bob);ctx.fillStyle='#06152188';ctx.fillRect(-13,10,26,6);ctx.fillStyle='#f6d565';ctx.fillRect(-12,-12,24,24);ctx.fillStyle='#fff0a0';ctx.fillRect(-9,-9,18,4);ctx.fillStyle='#bb793b';ctx.fillRect(-12,7,24,5);ctx.fillStyle='#3d3441';ctx.font='bold 15px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(({mega:'💪',oil:'🛢',spike:'✦',hook:'🪝'})[b.type],0,0);ctx.restore()}}
function drawOil(){for(const o of oils){ctx.globalAlpha=clamp(o.life/1.5,0,.7);ctx.fillStyle='#372c57';ctx.beginPath();ctx.ellipse(o.x,o.y,13,8,Math.sin(o.x),0,TAU);ctx.fill();ctx.globalAlpha=1}}
function drawPlayers(){for(const p of players){if(!p.alive)continue;if(p.invuln>0&&Math.floor(elapsed*14)%2)ctx.globalAlpha=.5;const size=p.power==='mega'?1.45:1;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(p.spin);ctx.scale(size,size);ctx.fillStyle='#07142177';ctx.fillRect(-p.r,-p.r+5,p.r*2,p.r*2);if(p.power==='spike'){ctx.strokeStyle='#d5f4ff';ctx.lineWidth=3;for(let i=0;i<8;i++){const a=i*TAU/8;ctx.beginPath();ctx.moveTo(Math.cos(a)*11,Math.sin(a)*11);ctx.lineTo(Math.cos(a)*20,Math.sin(a)*20);ctx.stroke()}}ctx.fillStyle=p.color;ctx.fillRect(-p.r,-p.r,p.r*2,p.r*2);ctx.fillStyle='#ffffff';ctx.fillRect(-p.r+3,-p.r+3,p.r*2-6,5);ctx.fillStyle='#242438';const fx=Math.cos(p.face)*3,fy=Math.sin(p.face)*2;ctx.fillRect(-5+fx,-3+fy,3,4);ctx.fillRect(3+fx,-3+fy,3,4);ctx.fillStyle='#ffffff';ctx.fillRect(-p.r+2,p.r-1,p.r*2-4,4);ctx.restore();ctx.globalAlpha=1;ctx.font='800 11px Nunito, sans-serif';ctx.textAlign='center';ctx.textBaseline='bottom';ctx.lineWidth=3;ctx.strokeStyle='#102035';ctx.strokeText(p===me?'TÚ':p.name,p.x,p.y-p.r-7);ctx.fillStyle=p===me?'#d8ff6a':'#fff';ctx.fillText(p===me?'TÚ':p.name,p.x,p.y-p.r-7);if(p===me){ctx.strokeStyle='#e7ff9a';ctx.lineWidth=2;ctx.strokeRect(p.x-p.r-3,p.y-p.r-3,p.r*2+6,p.r*2+6)}}}
function drawParticles(){for(const q of particles){ctx.globalAlpha=clamp(q.life/q.max,0,1);ctx.fillStyle=q.color;ctx.fillRect(q.x,q.y,q.size,q.size)}ctx.globalAlpha=1}
function frame(now){const dt=Math.min(.04,(now-last)/1000);last=now;update(dt);draw();requestAnimationFrame(frame)}
function setInput(e,down){const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keys[k]=down}
addEventListener('keydown',e=>setInput(e,true));addEventListener('keyup',e=>setInput(e,false));
document.getElementById('startBtn').addEventListener('click',startGame);document.getElementById('againBtn').addEventListener('click',startGame);
document.getElementById('dashBtn').addEventListener('pointerdown',e=>{e.preventDefault();input.dash=true});
const stick=document.getElementById('stick');let stickPointer=null;function moveStick(e){if(stickPointer!==e.pointerId)return;const r=stick.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=(e.clientX-cx)/(r.width*.38),dy=(e.clientY-cy)/(r.height*.38),m=Math.hypot(dx,dy);touchVector={x:dx/Math.max(1,m),y:dy/Math.max(1,m)};stick.style.setProperty('--dx',`${touchVector.x*25}px`);stick.style.setProperty('--dy',`${touchVector.y*25}px`)}stick.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',moveStick);function releaseStick(e){if(stickPointer===e.pointerId){stickPointer=null;touchVector={x:0,y:0};stick.style.setProperty('--dx','0px');stick.style.setProperty('--dy','0px')}}stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);
createPlayers();updateHUD();requestAnimationFrame(frame);
